set-variable.value:
@{
      var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      return request["method"] == null ? "" : request["method"].ToString();
    }

@{
      var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      var id = request["id"] == null ? "" : request["id"].ToString();
      return request["method"] == null
        && id.StartsWith("github-consent-", StringComparison.Ordinal);
    }

@{
      var response = (IResponse)context.Variables["toolbox-response"];
      if (!response.Headers.GetValueOrDefault("Content-Type", "")
        .Contains("application/json"))
      {
        return "";
      }
      var body = response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      var error = body["error"] as Newtonsoft.Json.Linq.JObject;
      return error == null || error["message"] == null
        ? ""
        : error["message"].ToString();
    }

return-response.set-body:
@{
            var message = (string)context.Variables["toolbox-error-message"];
            var details = Newtonsoft.Json.Linq.JObject.Parse(
              message.Substring(message.IndexOf("{", StringComparison.Ordinal))
            );
            var consentUrl = details["errors"][0]["error"]["message"].ToString();
            var eventId = Guid.NewGuid().ToString("N");
            var elicitationId = "github-consent-" + eventId;
            var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
            var elicitation = Newtonsoft.Json.JsonConvert.SerializeObject(new {
              jsonrpc = "2.0",
              id = elicitationId,
              method = "elicitation/create",
              @params = new {
                mode = "url",
                elicitationId = elicitationId,
                url = consentUrl,
                message = "Authorize GitHub to enable its tools in this Foundry toolbox."
              }
            });
            var listResponse = Newtonsoft.Json.JsonConvert.SerializeObject(new {
              jsonrpc = "2.0",
              id = request["id"],
              result = new {
                tools = new object[0]
              }
            });
            return "id: " + eventId + "-1\n"
              + "event: message\n"
              + "data: " + elicitation + "\n\n"
              + "id: " + eventId + "-2\n"
              + "event: message\n"
              + "data: " + listResponse + "\n\n";
          }
